import java.util.Scanner;
public class DisplayTime1 {
	public static void main(String[] args) {
		//Paso 1: Leer los segundos
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese un entero para los segundos: ");
		int seconds = scan.nextInt();
		scan.close();
		//Paso 2: Obtener minutos y segundos restantes a partir de los segundos ingresados
		int minutes = seconds / 60; 
		int remainingSeconds = seconds % 60;
		//Paso 3: Mostrar el resultado
		System.out.println(seconds + " segundos son " + minutes +    " minutos y " + remainingSeconds + " segundos.");  
	}
}

